// Package fixture is a generator plugin used by the plugin contract tests.
package fixture

import (
	"path/filepath"

	"github.com/azrtydxb/momo/gen"
)

// Plugin writes one generated file, and optionally one handwritten target.
type Plugin struct {
	Root      string
	Overwrite bool
}

// Name returns the plugin name.
func (Plugin) Name() string { return "fixture" }

// Generate writes its outputs through the writer only.
func (p Plugin) Generate(_ *gen.Graph, w *gen.Writer) error {
	src := []byte("// Code generated by momo (format 1). DO NOT EDIT.\n\npackage fixture\n")
	if err := w.File(filepath.Join(p.Root, "fixture", "zz_gen.go"), src); err != nil {
		return err
	}
	if p.Overwrite {
		return w.File(filepath.Join(p.Root, "handwritten", "hand.go"), []byte("package handwritten\n"))
	}
	return nil
}
